  ('au-skilled-independent', 1, '{"schemaVersion":1,"routeId":"au-skilled-independent","number":1,"title":"Australian Skilled Independent visa (subclass 189), points-tested stream: permanent residence for a skilled worker invited before turning 45","country":"AU","tags":["work","permanent-residence"],"effectiveFrom":"2026-07-01","status":"open","currency":"AUD","leapDayBirthday":"march-1","leapDayBirthdaySources":["acts-interpretation-age","legislation-act-instruments"],"sources":[{"id":"regs-1137-invitation","url":"https://www.legislation.gov.au/F1996B03551/latest/text","title":"Migration Regulations 1994, Schedule 1 item 1137(4B): invited in writing, applying within the invitation''s period, not 45 at invitation, nominating a listed skilled occupation","kind":"official","verifiedAt":"2026-11-07"},{"id":"regs-1137-charges","url":"https://www.legislation.gov.au/F1996B03551/latest/text","title":"Migration Regulations 1994, Schedule 1 item 1137(3) and (4), in force from 2026-07-01: first instalment of the visa application charge, and a second instalment for adults without functional English","kind":"official","verifiedAt":"2026-11-07"},{"id":"regs-189-criteria","url":"https://www.legislation.gov.au/F1996B03551/latest/text","title":"Migration Regulations 1994, Schedule 2 clauses 189.221 to 189.224: invitation, skills assessment for the nominated occupation, competent English at invitation, points score","kind":"official","verifiedAt":"2026-11-07"},{"id":"regs-points-test","url":"https://www.legislation.gov.au/F1996B03551/latest/text","title":"Migration Regulations 1994, regulation 2.26AC and Schedule 6D: the attributes and points of the points test; the Minister sets the pass mark by instrument (Migration Act, s. 96)","kind":"official","verifiedAt":"2026-11-07"},{"id":"regs-competent-english","url":"https://www.legislation.gov.au/F1996B03551/latest/text","title":"Migration Regulations 1994, regulation 1.15C: competent English by a specified test taken in the 3 years be