  ('ie-critical-skills', 2, '{"schemaVersion":1,"routeId":"ie-critical-skills","number":2,"corrects":1,"title":"Critical Skills Employment Permit for Ireland: a 2-year job offer in a critical skills occupation paying at least €40,904 a year, or any eligible job paying €68,911","country":"IE","tags":["work","temporary-residence"],"effectiveFrom":"2026-06-12","status":"open","currency":"EUR","leapDayBirthday":"feb-28","leapDayBirthdaySources":["age-of-majority-act"],"sources":[{"id":"ep-act-foreign-national","url":"https://www.irishstatutebook.ie/eli/2024/act/17/enacted/en/html","title":"Employment Permits Act 2024, ss. 2(1) and 7(1): a foreign national, a non-national within the Immigration Act 1999, may be in employment in the State only under an employment permit","kind":"official","verifiedAt":"2026-11-07"},{"id":"ep-act-eu-treaty-rights","url":"https://www.irishstatutebook.ie/eli/2024/act/17/enacted/en/html","title":"Employment Permits Act 2024, s. 8(1)(e): section 7 does not apply to a foreign national entitled to enter and work in the State under the treaties governing the European Union","kind":"official","verifiedAt":"2026-11-07"},{"id":"immigration-act-1999-non-national","url":"https://www.irishstatutebook.ie/eli/1999/act/22/section/1/enacted/en/html","title":"Immigration Act 1999, s. 1(1): a non-national is an alien under the Aliens Act 1935, other than an alien whom an order under s. 10 of that Act exempts from all of it","kind":"official","verifiedAt":"2026-11-07"},{"id":"aliens-exemption-order-1999","url":"https://www.irishstatutebook.ie/eli/1999/si/97/made/en/html","title":"Aliens (Exemption) Order 1999 (S.I. No. 97 of 1999), art. 3: every citizen of the United Kingdom is exempted from all the provisions of the Aliens Act 1935","kind":"official","verifiedAt":"2026-11-07"},{"id":"dete-who-needs-a-permit","url":"https://enterprise.gov.ie/en/what-we-do/workplace-and-skills/employment-permits/employment-permit-eligibility/who-needs-an-employment-permit-/","